// Browser-local prototype enhancements. Live permissions require server enforcement.
extras.staff=extras.staff||{};
const isStaff=()=>['Owner HQ','Barber Pro'].includes(state.role);
const scopedBookings=()=>bookings.filter(b=>(!state.scope||state.scope==='all'||(b.location||'scottsdale')===state.scope));
const scopePicker=()=>`<label class="field">Location<select id="calendar-scope"><option value="all">All locations</option>${Object.entries(shops).map(([id,s])=>`<option value="${id}" ${state.scope===id?'selected':''}>${s.name}</option>`).join('')}</select></label>`;
const prevRender=render;
function openStatus(now=new Date()){
 const p=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/Phoenix',weekday:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(now).map(x=>[x.type,x.value]));
 const schedule=extras.location==='university'?(p.weekday==='Mon'||p.weekday==='Tue'?[480,1320]:p.weekday==='Sat'||p.weekday==='Sun'?[450,1260]:[450,1320]):[540,1080];
 const [start,end]=schedule,minute=Number(p.hour)*60+Number(p.minute),open=minute>=start&&minute<end;
 const label=n=>`${Math.floor(n/60)%12||12}${n%60?':'+String(n%60).padStart(2,'0'):''} ${n>=720?'PM':'AM'}`;
 return {open,label:open?'Open until '+label(end):'Closed · Check shop hours'};
}
render=function(){prevRender();const status=openStatus(),loc=document.querySelector('.topbar .location');if(loc)loc.innerHTML=`${icon('pin')} ${esc(shops[extras.location||'scottsdale'].name)} <span class="dot ${status.open?'open-pulse':'closed-dot'}"></span>${status.label}`;
 if(state.role==='Barber Pro'&&state.view==='home')document.querySelector('.metric-strip')?.insertAdjacentHTML('afterend',staffStats(activeStaff()));
 if(isStaff()&&['home','pCalendar','calendar'].includes(state.view))document.querySelector('.page-head')?.insertAdjacentHTML('afterend',`<div class="flex-buttons booking-toolbar"><button class="btn small" data-enhance="booking">${icon('calendar')} Add booking</button></div>`);
 if(['pProfile','settings'].includes(state.view)){const form=document.querySelector('form');if(form&&!form.querySelector('[name="accountPhone"]'))form.insertAdjacentHTML('beforeend',`<label class="field">Phone number<input type="tel" name="accountPhone" value="${esc(extras.accountPhones?.[state.role]||'')}" autocomplete="tel"></label>`);}
};
setInterval(()=>{const dot=document.querySelector('.topbar .location');if(dot){const s=openStatus();dot.innerHTML=`${icon('pin')} ${esc(shops[extras.location||'scottsdale'].name)} <span class="dot ${s.open?'open-pulse':'closed-dot'}"></span>${s.label}`;}},60000);
const previousMetrics=metrics;
metrics=function(owner=false){if(!owner)return previousMetrics(false);const list=scopedBookings(),active=list.filter(b=>b.status!=='cancelled'),approved=active.filter(b=>b.ticket?.approval),revenue=approved.reduce((n,b)=>n+b.ticket.approval.totalCents,0);return `${scopePicker()}<div class="metric-strip">${[['Approved tickets',approved.length],['Approved total',cents(revenue)],['Appointments',active.length],['No-show rate',active.length?Math.round(active.filter(b=>b.status==='no-show').length/active.length*100)+'%':'—']].map(([k,v])=>`<div class="metric"><span>${k}</span><strong>${v}</strong><small>Recorded in this browser · selected locations</small></div>`).join('')}</div>`;};
function staffStats(b){const month=today.slice(0,7),list=scopedBookings().filter(x=>x.barber===b.id&&x.date.startsWith(month)),worked=new Set(list.filter(x=>x.date<=today&&x.ticket?.status==='approved').map(x=>x.date)).size,off=new Set(extras.blocks.filter(x=>x.barber===b.id&&x.date.startsWith(month)&&x.start==='00:00'&&x.end==='23:59').map(x=>x.date)).size,eligible=list.filter(x=>['completed','no-show'].includes(x.status)||x.ticket?.status==='approved');return `<div class="staff-stats"><span>Days worked this month <strong>${worked}</strong></span><span>Full days off this month <strong>${off}</strong></span><span>No-show rate <strong>${eligible.length?Math.round(eligible.filter(x=>x.status==='no-show').length/eligible.length*100)+'%':'—'}</strong></span></div>`;}
team=function(){return `${head('Your people. Your shop.','Stats from recorded visits and full-day time off.')}${scopePicker()}${barbers.map(b=>`<section class="panel staff-panel"><div class="row between"><div class="row">${photo(b)}<h2>${esc(b.name)}</h2></div><label>Employment<select data-employment="${b.id}" ${state.role!=='Owner HQ'?'disabled':''}>${['Full time','Part time'].map(v=>`<option ${v===(extras.staff[b.id]?.employment||'Full time')?'selected':''}>${v}</option>`).join('')}</select></label></div>${staffStats(b)}</section>`).join('')}`;};
const oldMember=memberPage;memberPage=function(){const b=barbers.find(x=>x.id===state.member)||activeStaff();return oldMember()+staffStats(b);};
proCalendar=function(owner=false){const list=(owner?scopedBookings():bookings.filter(b=>b.barber===activeBarberId())).filter(b=>b.date===state.calendarDate&&b.status!=='cancelled');return `${head(owner?'Every chair in sync.':'Your calendar.',owner?'Master calendar · Arizona time':activeStaff().name+' · Arizona time',`<div class="date-nav"><button class="icon-btn" data-action="prev-day" aria-label="Previous day">${icon('back')}</button><input type="date" id="agenda-date" value="${state.calendarDate}"><button class="icon-btn" data-action="next-day" aria-label="Next day">${icon('chevron')}</button></div>`)}${owner?scopePicker():''}<section class="panel">${list.length?list.sort((a,b)=>minutes(a.time)-minutes(b.time)).map(b=>{const barber=barbers.find(x=>x.id===b.barber);return `<div class="list-item"><time>${esc(b.time)}</time><div class="details"><h3>${esc(b.client)}</h3><p>${esc(bookingName(b))} · ${esc(shops[b.location||'scottsdale'].name)}</p></div><div class="row">${photo(barber)}<strong>${esc(barber.name)}</strong></div></div>`;}).join(''):'<p class="muted">No appointments recorded for this day.</p>'}</section>${extras.blocks.filter(b=>b.date===state.calendarDate&&(owner||b.barber===activeBarberId())).map(b=>`<div class="notice">${esc(barbers.find(x=>x.id===b.barber)?.name||'Barber')} · ${esc(b.reason)} · ${b.start}–${b.end}</div>`).join('')}`;};
const oldReports=reports;reports=function(){return `${head('Know what’s working.','Selected location performance.')}${metrics(true)}${barbers.map(b=>`<section class="panel staff-panel"><h2>${esc(b.name)}</h2>${staffStats(b)}</section>`).join('')}`;};
const oldHelp=helpPage;helpPage=function(){return `<div class="support-layout"><section>${oldHelp()}</section><aside class="panel"><h2>Talk to us</h2><button class="btn full" data-enhance="barber-message">${icon('message')} Message your barber</button><button class="btn secondary full" data-x="general-thread">${icon('message')} Message shop</button></aside></div>`;};
const oldPayment=paymentsPage;paymentsPage=function(){return oldPayment()+`<section class="panel payment-preview"><h2>Card & wallets</h2><p class="muted">Payments will be available once Stripe is connected. No card details are collected here.</p><fieldset disabled><label class="field">Cardholder name<input placeholder="Name on card" tabindex="-1"></label><label class="field">Card number<input placeholder="•••• •••• •••• ••••" tabindex="-1"></label><div class="row"><label class="field">Expiry<input placeholder="MM / YY" tabindex="-1"></label><label class="field">Security code<input placeholder="CVC" tabindex="-1"></label></div><button class="btn full" disabled>Save card · Coming soon</button><div class="flex-buttons"><button class="btn secondary" disabled>Apple Pay</button><button class="btn secondary" disabled>Google Pay</button></div></fieldset></section>`;};
function manualBooking(){if(!isStaff())return '';return `${head('Add an appointment.','Choose the client, barber and time.')}<form id="manual-booking" class="panel narrow"><label class="field">Client name<input name="client" required maxlength="80"></label><label class="field">Phone number<input name="phone" type="tel" maxlength="30"></label><label class="field">Location<select name="location">${Object.entries(shops).map(([id,s])=>`<option value="${id}" ${id===extras.location?'selected':''}>${s.name}</option>`).join('')}</select></label><label class="field">Barber<select name="barber">${barbers.filter(b=>state.role==='Owner HQ'||b.id===activeBarberId()).map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></label><label class="field">Service<select name="service">${services.filter(s=>s.active!==false).map(s=>`<option value="${s.id}">${esc(s.name)} · ${s.min} min</option>`).join('')}</select></label><label class="field">Date<input type="date" name="date" min="${today}" value="${state.calendarDate<today?today:state.calendarDate}" required></label><label class="field">Time<select name="time">${times.map(t=>`<option>${t}</option>`).join('')}</select></label><p id="booking-error" role="alert"></p><button class="btn">Add booking</button></form>`;}
let dragStart=null,dragEnd=null;
function availability(){const anchor=state.availabilityStart||today,dates=Array.from({length:14},(_,i)=>{const d=dateObj(anchor);d.setDate(d.getDate()+i);return iso(d);});return `${head('Make room for life.','Drag across days to select time off. Tap a start and end day on mobile.')}<section class="panel"><label class="field">Calendar starts<input type="date" id="availability-start" value="${anchor}" min="${today}"></label><div class="vacation-grid">${dates.map(d=>`<button type="button" class="vacation-day ${extras.blocks.some(b=>b.barber===activeBarberId()&&b.date===d)?'blocked':''}" data-day="${d}" aria-label="${pretty(d)}">${pretty(d)}${extras.blocks.some(b=>b.barber===activeBarberId()&&b.date===d)?'<small>Time blocked</small>':''}</button>`).join('')}</div><form id="vacation-form"><div class="row"><label class="field">From<input type="date" name="from" min="${today}" required></label><label class="field">Through<input type="date" name="through" min="${today}" required></label></div><label class="field">Reason<input name="reason" value="Vacation" maxlength="80" required></label><label class="check-row"><input type="checkbox" name="allDay" checked> Full days off</label><div class="row"><label class="field">From time<input type="time" name="start" value="09:00" required></label><label class="field">Until<input type="time" name="end" value="18:00" required></label></div><p id="vacation-error" role="alert"></p><button class="btn">Save time off</button></form></section>${extras.blocks.filter(b=>b.barber===activeBarberId()).map(b=>`<div class="list-item"><div class="details"><strong>${esc(b.reason)}</strong><p>${pretty(b.date)} · ${b.start}–${b.end}</p></div>${xbutton('Remove','remove-block','secondary small',`data-id="${b.id}"`)}</div>`).join('')}`;}
const oldExtra=renderExtraView;renderExtraView=function(v){if(v==='manualBooking')return isStaff()?manualBooking():head('Staff access required.','');if(v==='pBlock')return availability();return oldExtra(v);};
function selectDays(a,b){const dates=[a,b].sort(),form=document.querySelector('#vacation-form');if(!form)return;form.elements.from.value=dates[0];form.elements.through.value=dates[1];document.querySelectorAll('[data-day]').forEach(el=>el.classList.toggle('selected',el.dataset.day>=dates[0]&&el.dataset.day<=dates[1]));}
document.addEventListener('pointerdown',e=>{const el=e.target.closest('[data-day]');if(!el)return;if(e.pointerType==='touch'){if(!dragStart){dragStart=el.dataset.day;selectDays(dragStart,dragStart);}else{selectDays(dragStart,el.dataset.day);dragStart=null;}return;}e.preventDefault();dragStart=el.dataset.day;dragEnd=dragStart;selectDays(dragStart,dragEnd);});
document.addEventListener('pointerover',e=>{const el=e.target.closest('[data-day]');if(el&&dragStart&&e.buttons===1){dragEnd=el.dataset.day;selectDays(dragStart,dragEnd);}});
document.addEventListener('pointerup',e=>{if(e.pointerType!=='touch')dragStart=null;});
document.addEventListener('click',e=>{const d=e.target.closest('[data-enhance]')?.dataset;if(d?.enhance==='booking'&&isStaff())go('manualBooking');if(d?.enhance==='barber-message'){state.barber=extras.saved?.[0]||'alex';state.threadId=threadFor('John B.',state.barber).id;go('messages');}});
document.addEventListener('change',e=>{if(e.target.id==='calendar-scope'){state.scope=e.target.value;render();}if(e.target.id==='agenda-date'){state.calendarDate=e.target.value||today;render();}if(e.target.id==='availability-start'){state.availabilityStart=e.target.value||today;render();}if(e.target.dataset.employment&&state.role==='Owner HQ'){const id=e.target.dataset.employment;extras.staff[id]={...extras.staff[id],employment:e.target.value};save();}});
function conflict(barber,date,start,duration){return bookings.some(b=>b.barber===barber&&b.date===date&&b.status!=='cancelled'&&minutes(b.time)<start+duration&&minutes(b.time)+bookingDuration(b)>start)||extras.blocks.some(b=>b.barber===barber&&b.date===date&&clockMinutes(b.start)<start+duration&&clockMinutes(b.end)>start);}
document.addEventListener('submit',e=>{const f=e.target,d=new FormData(f);if(f.querySelector('[name="accountPhone"]')){extras.accountPhones=extras.accountPhones||{};extras.accountPhones[state.role]=String(d.get('accountPhone')||'').trim();save();}
 if(f.id==='manual-booking'){e.preventDefault();if(!isStaff())return;try{const barber=state.role==='Barber Pro'?activeBarberId():String(d.get('barber')),s=services.find(s=>s.id===d.get('service')),date=String(d.get('date')),time=String(d.get('time'));if(!s||!barbers.some(b=>b.id===barber)||!shops[d.get('location')]||!times.includes(time)||date<today)throw Error('Choose a valid appointment.');if(conflict(barber,date,minutes(time),s.min))throw Error('This barber is already booked or unavailable at that time.');bookings.push({id:'staff-'+Date.now(),client:String(d.get('client')).trim(),phone:String(d.get('phone')||'').trim(),barber,service:s.id,bookedServices:[{...s}],durationMin:s.min,estimateCents:Math.round(s.price*100),date,time,location:String(d.get('location')),status:'confirmed'});save();go(state.role==='Owner HQ'?'calendar':'pCalendar');toast('Appointment added to this browser’s schedule.');}catch(err){f.querySelector('#booking-error').textContent=err.message;}}
 if(f.id==='vacation-form'){e.preventDefault();if(!isStaff())return;try{const from=String(d.get('from')),through=String(d.get('through')),start=d.has('allDay')?'00:00':String(d.get('start')),end=d.has('allDay')?'23:59':String(d.get('end'));if(!from||!through||from<today||through<from||end<=start)throw Error('Select a valid date range and time.');const dates=[];for(let day=from;day<=through;){if(dates.length>=366)throw Error('Select no more than one year.');dates.push(day);const next=dateObj(day);next.setDate(next.getDate()+1);day=iso(next);}if(dates.some(date=>bookings.some(b=>b.barber===activeBarberId()&&b.date===date&&b.status!=='cancelled'&&minutes(b.time)<clockMinutes(end)&&minutes(b.time)+bookingDuration(b)>clockMinutes(start))))throw Error('An appointment overlaps this time off. Reschedule it first.');for(const date of dates)extras.blocks.push({id:'block-'+date+'-'+Date.now(),barber:activeBarberId(),date,start,end,reason:String(d.get('reason')).trim()});save();render();toast('Time off saved. These times cannot be booked.');}catch(err){f.querySelector('#vacation-error').textContent=err.message;}}
});
render();
